// 普通写法拆成三步
// 第一步：声明引用变量（造一个 Dog 遥控器，按钮只有 Dog 能响应的）
Dog myDog;
// 第二步：创建对象（在堆上造一台 Dog 电视）
myDog = new Dog();
// 第三步其实合并在上面这行：把电视频率写进遥控器

// 也可以一行写完，含义完全相同：
Dog myDog2 = new Dog();       // 引用类型 Dog，对象类型 Dog，两边一样

// 多态写法：只改第一步的引用类型
Animal myAnimal = new Dog();  // 引用类型 Animal，对象类型 Dog，两边不同
// 为什么合法：Dog IS-A Animal
// 为什么安全：Animal 有的方法 Dog 一定有（继承或覆盖）
// 变的是什么：遥控器从 Dog 版换成 Animal 版，按钮变少
// 不变的是什么：堆上那个对象仍然是完整的 Dog

// myAnimal.bark();  // 编译失败：Animal 遥控器没有 bark 这个按钮

Animal[] animals = new Animal[5];   // 建的是数组对象，不是 5 个 Animal 实例
animals[0] = new Dog();             // 每个槽位装一个子类对象的引用
animals[1] = new Cat();
animals[2] = new Wolf();
animals[3] = new Hippo();
animals[4] = new Lion();

for (Animal animal : animals) {     // animal 的编译期类型是 Animal
    animal.eat();                   // 同一行代码，五轮跑五个不同实现
    animal.roam();                  // 狗跑 Canine 群居版，猫跑 Feline 独行版
}

